<script setup lang="ts">
import {computed, onMounted, onBeforeUnmount, ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowUpRight, CheckCircle, ChevronRight, Clock, Lock, Mail, Plus} from 'lucide-vue-next'
import {capsuleApi} from '@/api'
import {useFamilyStore} from '@/stores/family'
import type {Capsule} from '@/types'
import FlipNumber from '@/components/FlipNumber.vue'
import WaxSeal from '@/components/WaxSeal.vue'
import OrbitalScene from '@/components/OrbitalScene.vue'
import MagneticAction from '@/components/MagneticAction.vue'
import GlowCollection from '@/components/GlowCollection.vue'
import SegmentedControl from '@/components/SegmentedControl.vue'
import {usePageMotion} from '@/composables/usePageMotion'


import {readViewState,writeViewState} from '@/composables/viewState'



const family = useFamilyStore()
const route=useRoute(),router=useRouter(),vaultRoot=ref<HTMLElement>()
usePageMotion(vaultRoot)
const capsules = ref<Capsule[]>([])
const filter = ref<'all' | 'pending' | 'opened'>(route.query.filter==='pending'?'pending':route.query.filter==='opened'?'opened':'all')
const loading = ref(true)
const loadError = ref('')
function openCapsule(){window.dispatchEvent(new Event('family-capsule-compose'))}
function changeFilter(value:string){filter.value=value as typeof filter.value;void router.replace({query:{...route.query,filter:value}})}
watch(()=>route.query.filter,value=>{if(value==='all'||value==='pending'||value==='opened')filter.value=value})
const next = computed(() => capsules.value.filter(item => !item.opened).sort((a,b) => a.daysRemaining - b.daysRemaining)[0])
const pendingCount = computed(() => capsules.value.filter(item => !item.opened).length)
const openedCount = computed(() => capsules.value.filter(item => item.opened).length)
const filteredCapsules = computed(() => filter.value === 'all' ? capsules.value : capsules.value.filter(item => filter.value === 'opened' ? item.opened : !item.opened))

async function load(){if(!family.current)return;loading.value=true;loadError.value='';try{capsules.value=await capsuleApi.list(family.current.id)}catch(e){loadError.value=(e as Error).message}finally{loading.value=false}}
onMounted(async () => { if (!family.current) await family.load(); const saved=readViewState<{filter:typeof filter.value;scroll:number}>(`vault:${family.current?.id}`);if(saved&&!route.query.filter)filter.value=saved.filter;await load();if(saved)requestAnimationFrame(()=>document.querySelector('[data-app-scroll]')?.scrollTo({top:saved.scroll}));window.addEventListener('family-capsule-created',load) })
onBeforeUnmount(()=>{writeViewState(`vault:${family.current?.id}`,{filter:filter.value,scroll:document.querySelector('[data-app-scroll]')?.scrollTop||0});window.removeEventListener('family-capsule-created',load)})

</script>
<template>
  <section ref="vaultRoot" class="vault-page page-reveal">
    <header class="voyage-heading"><div><p class="observatory-kicker"><span></span> THE LIGHT WE SEND <i>02 / 珍藏</i></p><h1>让此刻的心意，<em>在未来发光。</em></h1><p>有些话，值得等一个特别的日子。<br class="mobile-break">把今天的光，交给时间慢慢送达。</p></div><div class="voyage-compose"><MagneticAction label="封存一份心意" @activate="openCapsule"/></div></header>
    <div v-if="loading" class="post-loading" role="status"><Mail :size="28" aria-hidden="true"/><p>正在寻找时间里的来信…</p></div>
    <div v-else-if="loadError" class="post-error" role="alert"><h2>来信暂时未能送达</h2><p>{{loadError}}</p><button class="sky-secondary" @click="load">重新加载</button></div>
    <template v-else>
      <section v-if="next" class="voyage-dispatch" aria-label="下一封来信" data-reveal>
        <div class="voyage-story"><p class="voyage-label"><span></span> IN TRANSIT <i>/ 下一份约定</i></p><p class="voyage-recipient">写给 {{next.recipient||'未来的家人'}}</p><h2>{{next.title}}</h2><p class="voyage-description">此刻的心意，正在穿过时间。<br>等到那一天，再一起打开今天的光。</p><RouterLink :to="`/capsules/${next.id}`" class="voyage-detail">{{next.daysRemaining<=0?'赴一场重逢':'查看这份约定'}}<span><ArrowUpRight :size="18" aria-hidden="true"/></span></RouterLink></div>
        <div class="voyage-object"><OrbitalScene variant="capsule"/><RouterLink :to="`/capsules/${next.id}`" class="celestial-envelope" :aria-label="`查看${next.title}，还有${Math.max(0,next.daysRemaining)}天`"><div class="envelope-back" aria-hidden="true"></div><div class="envelope-letter"><span class="envelope-route">拾光慢递 <i>✧</i> SENT WITH LOVE</span><span class="envelope-count-label">{{next.daysRemaining<=0?'约定已至，星光抵达':'距离星光抵达，还有'}}</span><strong class="envelope-count"><FlipNumber :value="Math.max(0,next.daysRemaining)"/><small>天</small></strong><span class="envelope-to">TO. {{next.recipient||'未来的家人'}}</span></div><div class="envelope-front" aria-hidden="true"></div><div class="envelope-starlight-seal" aria-hidden="true"><WaxSeal/></div><span class="envelope-caption">{{next.openDate.split('-').join(' . ')}} · 约定重逢</span></RouterLink></div>
        <footer class="voyage-dates"><span><small>SEALED / 封存</small><time>{{next.createdAt.slice(0,10).split('-').join(' . ')}}</time></span><div aria-hidden="true"><i></i><b>✧</b><i></i></div><span><small>RENDEZVOUS / 重逢</small><time>{{next.openDate.split('-').join(' . ')}}</time></span></footer>
      </section>
      <section v-else class="vault-invitation" data-reveal><OrbitalScene variant="capsule"/><div><span aria-hidden="true">✧</span><h2>{{capsules.length?'星光已经抵达，下一份心意写给谁？':'把今天的心意，留在未来的星海。'}}</h2><p>写给长大的孩子、未来的自己，或一直在身边的人。</p><button class="voyage-detail" @click="openCapsule">写下新的约定<ArrowUpRight :size="18" aria-hidden="true"/></button></div></section>
      <header class="vault-collection-heading" data-reveal><div><span>02 /</span><h2>星光保管室 <small>A LITTLE CLOSER TO SOMEDAY</small></h2></div><p><b>{{capsules.length}}</b> 份心意，时间替你珍藏</p></header>
      <div class="vault-toolbar" data-reveal><SegmentedControl :model-value="filter" :options="[{value:'all',label:`全部 ${capsules.length}`},{value:'pending',label:`等待重逢 ${pendingCount}`},{value:'opened',label:`已抵达 ${openedCount}`}]" label="珍藏状态" @update:model-value="changeFilter"/><span><Lock :size="12" aria-hidden="true"/>未到约定的那天，心意只留在时间里。</span></div>
      <GlowCollection v-if="filteredCapsules.length" class="vault-letters"><RouterLink v-for="(item,index) in filteredCapsules" :key="item.id" :to="`/capsules/${item.id}`" class="u228-c capsule-collection-item" :class="{'letter-opened':item.opened}" :style="{'--item-delay':`${index*45}ms`}" data-reveal><article class="u228-in capsule-collection-surface"><header><span>NO. {{String(index+1).padStart(2,'0')}} <i>/</i> 星光档案</span><span class="capsule-collection-state"><CheckCircle v-if="item.opened" :size="12" aria-hidden="true"/><span v-else class="capsule-status-dot"></span>{{item.opened?'已经抵达':'时间守护中'}}</span></header><div class="capsule-mini-envelope" aria-hidden="true"><span>✧</span><Mail :size="37" :stroke-width=".7"/></div><p class="capsule-addressee">TO. <span>{{item.recipient||'未来的家人'}}</span></p><h3>{{item.title}}</h3><p class="capsule-excerpt">{{item.opened?item.content||'一份交给未来的心意。':'藏着今天的温柔，等待某一天的重逢。'}}</p><footer><div><Clock :size="12" aria-hidden="true"/><time>{{item.openDate}}</time></div><strong>{{item.opened?'重读来信':item.daysRemaining<=0?'约定已至':`还有 ${item.daysRemaining} 天`}}<ArrowUpRight :size="16" aria-hidden="true"/></strong></footer></article></RouterLink></GlowCollection>
      <div v-else class="post-empty" role="status"><span aria-hidden="true">✧</span><h3>{{filter==='all'?'未来，正在等你的第一份心意':filter==='pending'?'每一份心意，都已抵达':'美好的重逢，还在路上'}}</h3><p>{{filter==='all'?'写下一段现在的话，寄给未来值得期待的一天。':'换个状态看看，或写下一份新的约定。'}}</p><button class="voyage-detail" @click="filter==='all'?openCapsule():changeFilter('all')">{{filter==='all'?'写下第一份约定':'查看全部珍藏'}}<ArrowUpRight :size="16" aria-hidden="true"/></button></div>
      <p class="post-colophon"><span></span>星光走得很慢，爱会如期抵达。<span></span></p>
    </template>
  </section>
</template>
<style scoped>
